1	import * as fs from "node:fs";
2	import * as path from "node:path";
3	import { sha256 } from "./hash";
4	import { downloadBlob, listRemoteBlobs, uploadBlob } from "./httpClient";
5	import { walkFiles } from "./walk";
6	
7	export interface SyncResult {
8	  uploaded: string[];
9	  downloaded: string[];
10	  unchanged: string[];
11	  failed: { key: string; error: string }[];
12	}
13	
14	// Manifest lives inside <dir> because that's the only thing that persists
15	// between separate `run-client sync` invocations (each is a fresh
16	// container with just <dir> mounted). It's excluded from the set of keys
17	// being synced so it never gets pushed/pulled as if it were user content.
18	const MANIFEST_RELATIVE_PATH = [".syncbox", "manifest.json"];
19	const MANIFEST_KEY = MANIFEST_RELATIVE_PATH.join("/");
20	
21	// key -> sha256 of the content last known to be identical on both sides.
22	type Manifest = Record<string, string>;
23	
24	function manifestPath(dir: string): string {
25	  return path.join(dir, ...MANIFEST_RELATIVE_PATH);
26	}
27	
28	function loadManifest(dir: string): Manifest {
29	  try {
30	    return JSON.parse(fs.readFileSync(manifestPath(dir), "utf8")) as Manifest;
31	  } catch {
32	    return {};
33	  }
34	}
35	
36	function saveManifest(dir: string, manifest: Manifest): void {
37	  const p = manifestPath(dir);
38	  fs.mkdirSync(path.dirname(p), { recursive: true });
39	  fs.writeFileSync(p, JSON.stringify(manifest, null, 2));
40	}
41	
42	function localPath(dir: string, key: string): string {
43	  return path.join(dir, ...key.split("/"));
44	}
45	
46	/**
47	 * Bidirectionally syncs <dir> with the server: a key present on only one
48	 * side is copied to the other; a key that diverges on both sides is
49	 * resolved per SYNCBOX-SPEC.md's "Правило разрешения конфликтов для
50	 * sync" using a manifest of the last known common SHA-256 per key,
51	 * persisted under <dir>/.syncbox/manifest.json. Never deletes a file on
52	 * either side — a key missing on one side is treated as "not yet copied
53	 * there", not as a deletion to propagate.
54	 */
55	export async function sync(dir: string, server: string): Promise<SyncResult> {
56	  const manifest = loadManifest(dir);
57	
58	  const remote = await listRemoteBlobs(server);
59	  const remoteByKey = new Map(
60	    remote.filter((blob) => blob.key !== MANIFEST_KEY).map((blob) => [blob.key, blob])
61	  );
62	
63	  const localKeys = walkFiles(dir).filter((key) => key !== MANIFEST_KEY);
64	  const localHashes = new Map<string, string>();
65	  for (const key of localKeys) {
66	    localHashes.set(key, sha256(fs.readFileSync(localPath(dir, key))));
67	  }
68	
69	  const allKeys = new Set([...localHashes.keys(), ...remoteByKey.keys()]);
70	
71	  const uploaded: string[] = [];
72	  const downloaded: string[] = [];
73	  const unchanged: string[] = [];
74	  const failed: { key: string; error: string }[] = [];
75	  const nextManifest: Manifest = { ...manifest };
76	
77	  for (const key of [...allKeys].sort()) {
78	    const localHash = localHashes.get(key);
79	    const remoteBlob = remoteByKey.get(key);
80	    const remoteHash = remoteBlob?.sha256;
81	    const absPath = localPath(dir, key);
82	
83	    try {
84	      if (remoteHash === undefined) {
85	        // local-only: push it.
86	        await uploadBlob(server, key, fs.readFileSync(absPath));
87	        uploaded.push(key);
88	        nextManifest[key] = localHash!;
89	        continue;
90	      }
91	
92	      if (localHash === undefined) {
93	        // server-only: pull it.
94	        const content = await downloadBlob(server, key);
95	        fs.mkdirSync(path.dirname(absPath), { recursive: true });
96	        fs.writeFileSync(absPath, content);
97	        downloaded.push(key);
98	        nextManifest[key] = remoteHash;
99	        continue;
100	      }
101	
102	      if (localHash === remoteHash) {
103	        unchanged.push(key);
104	        nextManifest[key] = localHash;
105	        continue;
106	      }
107	
108	      // Both sides have the key with different content. Figure out which
109	      // side actually changed relative to the last known common state.
110	      const baseline = manifest[key];
111	      const onlyLocalChanged = baseline !== undefined && baseline === remoteHash;
