1	export interface RemoteBlobMeta {
2	  key: string;
3	  size: number;
4	  sha256: string;
5	  modified_at: string;
6	}
7	
8	const REQUEST_TIMEOUT_MS = 10_000;
9	
10	function joinUrl(server: string, pathname: string): string {
11	  return `${server.replace(/\/+$/, "")}${pathname}`;
12	}
13	
14	/**
15	 * Turns a fetch() rejection into a message that names the actual cause
16	 * (refused, unresolvable host, reset, timeout) instead of undici's generic
17	 * "fetch failed" — the spec requires the client to say why the server was
18	 * unreachable, not just that it was.
19	 */
20	function describeConnectionError(
21	  err: unknown,
22	  server: string,
23	  timeoutMs: number
24	): string {
25	  const error = err as Error & { cause?: NodeJS.ErrnoException };
26	
27	  if (error.name === "TimeoutError" || error.name === "AbortError") {
28	    return `timed out waiting for ${server} (no response within ${timeoutMs}ms)`;
29	  }
30	
31	  switch (error.cause?.code) {
32	    case "ECONNREFUSED":
33	      return `connection to ${server} refused (is the server running?)`;
34	    case "ENOTFOUND":
35	    case "EAI_AGAIN":
36	      return `could not resolve host for ${server}`;
37	    case "ECONNRESET":
38	      return `connection to ${server} was reset while communicating`;
39	    default:
40	      return `could not reach ${server}: ${error.cause?.message ?? error.message}`;
41	  }
42	}
43	
44	/**
45	 * Encodes a key for use in a /blobs/{key} URL: each path segment is
46	 * percent-encoded individually and rejoined with literal "/", so the
47	 * server's single decodeURIComponent(rawTail) call reconstructs the exact
48	 * original key instead of mangling `/` embedded inside a segment.
49	 */
50	export function encodeKeyPath(key: string): string {
51	  return key
52	    .split("/")
53	    .map((segment) => encodeURIComponent(segment))
54	    .join("/");
55	}
56	
57	async function fetchWithTimeout(
58	  url: string,
59	  init: RequestInit,
60	  server: string
61	): Promise<Response> {
62	  try {
63	    return await fetch(url, {
64	      ...init,
65	      signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS),
66	    });
67	  } catch (err) {
68	    throw new Error(describeConnectionError(err, server, REQUEST_TIMEOUT_MS));
69	  }
70	}
71	
72	export async function listRemoteBlobs(
73	  server: string
74	): Promise<RemoteBlobMeta[]> {
75	  const url = joinUrl(server, "/blobs");
76	  const res = await fetchWithTimeout(url, { method: "GET" }, server);
77	
78	  if (!res.ok) {
79	    throw new Error(
80	      `GET /blobs failed: server responded ${res.status} ${res.statusText}`
81	    );
82	  }
83	  return (await res.json()) as RemoteBlobMeta[];
84	}
85	
86	export async function downloadBlob(
87	  server: string,
88	  key: string
89	): Promise<Buffer> {
90	  const url = joinUrl(server, `/blobs/${encodeKeyPath(key)}`);
91	  const res = await fetchWithTimeout(url, { method: "GET" }, server);
92	
93	  if (!res.ok) {
94	    throw new Error(
95	      `GET /blobs/${key} failed: server responded ${res.status} ${res.statusText}`
96	    );
97	  }
98	  return Buffer.from(await res.arrayBuffer());
99	}
100	
101	export async function uploadBlob(
102	  server: string,
103	  key: string,
104	  content: Buffer
105	): Promise<void> {
106	  const url = joinUrl(server, `/blobs/${encodeKeyPath(key)}`);
107	  const res = await fetchWithTimeout(
108	    url,
109	    { method: "PUT", body: content },
110	    server
111	  );
112	
