      }
      return (original as (...args: unknown[]) => unknown)(target, opts);
    }) as typeof fs.readFileSync);

    const result = await sync(dir, server.url);

    expect(result.uploaded).toEqual(["good.txt"]);
    expect(result.failed).toEqual([
      { key: "unreadable.txt", error: expect.stringContaining("EACCES") },
    ]);
    expect(server.uploadedContent("unreadable.txt")).toBeUndefined();
  });
});

